:root{--fn-ink:#173e3b;--fn-muted:#536962;--fn-paper:#f7f6ef;--fn-line:#d6ded5;--fn-lime:#d8ed9b;--global-palette1:#173e3b;--global-palette2:#275b50;--global-palette3:#173e3b;--global-palette4:#344f48;--global-palette5:#536962;--global-palette9:#fff;--global-body-font-family:Arial,Helvetica,sans-serif}
html{scroll-behavior:smooth}body{background:var(--fn-paper);color:var(--fn-ink);font-family:Arial,Helvetica,sans-serif;font-size:17px;line-height:1.7}a{color:inherit}a:focus-visible,button:focus-visible{outline:3px solid #66832d;outline-offset:5px}#masthead{border-bottom:1px solid var(--fn-line);background:var(--fn-paper)}.site-header-row-container-inner{background:var(--fn-paper)!important}.site-branding .site-title{font-family:Georgia,serif;font-size:30px;letter-spacing:-1px}.site-header-row-container-inner>.site-container{max-width:1280px;padding:0 40px}.primary-navigation .primary-menu-container>ul>li>a{font-size:14px;font-weight:600;color:var(--fn-ink)}.entry-hero,.entry-header{display:none}.content-area{margin:0}.content-container{max-width:none;padding:0}.entry-content-wrap{padding:0}.entry-content{margin:0}.entry-content>*,.entry-content>.wp-block-kadence-rowlayout{margin-block:0}.site-main{margin:0}.content-bg{background:var(--fn-paper)}
.fn-section{padding:80px 40px!important}.fn-section>.kt-row-column-wrap{max-width:1200px!important;margin-inline:auto;column-gap:56px}.fn-hero{padding-top:88px!important;padding-bottom:88px!important}.fn-eyebrow{font-size:12px!important;letter-spacing:2.2px;text-transform:uppercase;font-weight:700;margin:0 0 25px!important}.fn-hero-title{font-family:Georgia,serif!important;letter-spacing:-3.5px;font-weight:400!important;font-size:76px!important;line-height:1.06!important;max-width:650px;margin:0 0 26px!important}.fn-lead{font-size:19px!important;line-height:1.7!important;color:var(--fn-muted)!important;max-width:540px;margin:0 0 30px!important}.fn-section-title{font-family:Georgia,serif!important;font-size:46px!important;font-weight:400!important;letter-spacing:-1.8px;line-height:1.15!important;margin:0 0 22px!important}.fn-button .wp-block-button__link{border-radius:0;background:var(--fn-ink);color:#fff;padding:16px 24px;font-size:15px;font-weight:600;text-decoration:none;box-shadow:none}.fn-button .wp-block-button__link:hover{background:#275b50}.fn-note{font-size:13px;color:var(--fn-muted);margin-top:20px!important}.fn-rule{border-top:1px solid var(--fn-line)}.fn-white{background:#fff}.fn-dark{background:var(--fn-ink);color:#fff}.fn-dark h2,.fn-dark h3,.fn-dark p{color:#fff!important}.fn-dark .fn-eyebrow{color:var(--fn-lime)!important}.fn-dark .wp-block-button__link{background:var(--fn-lime);color:var(--fn-ink)}.fn-grid{gap:30px}.fn-card{border-top:2px solid var(--fn-ink);padding-top:24px}.fn-number{font-size:13px;font-weight:700;letter-spacing:1px;color:#637969;margin-bottom:30px!important}.fn-card h3{font-family:Georgia,serif;font-size:27px;font-weight:400;line-height:1.25;margin:0 0 12px}.fn-card p{font-size:16px;color:var(--fn-muted);margin:0 0 20px}.fn-arrow-link{font-size:14px;font-weight:700;text-decoration:none;border-bottom:1px solid #8c9e94;padding-bottom:3px}.fn-kicker{font-size:14px;font-weight:600;border-top:1px solid var(--fn-line);padding:20px 40px;margin:0;display:flex;gap:35px;justify-content:center;flex-wrap:wrap}.fn-kicker span:before{content:'+';color:#627e41;margin-right:12px}.fn-visual{padding:34px;background:#e5eadb;min-height:405px;border-radius:2px;position:relative;overflow:hidden}.fn-visual-label{display:flex;justify-content:space-between;font-size:11px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;margin-bottom:38px}.fn-visual-top{background:var(--fn-ink);color:white;padding:22px 25px;font-family:Georgia,serif;font-size:25px;max-width:260px;margin-inline:auto;position:relative;z-index:1}.fn-visual-line{height:36px;border-left:1px solid #7d957a;width:1px;margin:auto}.fn-visual-branches{display:grid;grid-template-columns:1fr 1fr;gap:16px;position:relative}.fn-visual-branches:before{content:'';position:absolute;top:0;left:25%;right:25%;border-top:1px solid #7d957a}.fn-visual-step{padding:22px 18px;background:#f7f8ee;border:1px solid #b8c5ac;font-size:14px;text-align:center}.fn-visual-step b{display:block;font-size:12px;letter-spacing:1px;color:#688254;margin-bottom:7px}.fn-visual-footer{display:flex;align-items:center;gap:12px;font-size:12px;color:#41593f;margin-top:27px}.fn-dot{height:8px;width:8px;background:#688254;border-radius:50%}.fn-process{counter-reset:step}.fn-process>div{display:flex;gap:22px;border-top:1px solid var(--fn-line);padding:24px 0}.fn-process b{font-size:13px;color:#638057;padding-top:4px}.fn-process h3{font-family:Georgia,serif;font-weight:400;font-size:25px;margin:0 0 8px}.fn-process p{font-size:15px;color:var(--fn-muted);margin:0}.fn-body{max-width:800px;margin:auto}.fn-body p,.fn-body li{color:var(--fn-muted)}.fn-body h2{font-family:Georgia,serif;font-size:34px;font-weight:400;line-height:1.2;margin-top:45px}.fn-contact-box{border:1px solid var(--fn-line);padding:32px;background:white}.fn-contact-box a{overflow-wrap:anywhere}.fn-demo-notice{padding:18px 24px;text-align:center;background:#e8ecdf;color:#42593e;font-size:12px;border-top:1px solid var(--fn-line)}.site-bottom-footer-wrap{background:var(--fn-paper);font-size:12px}.footer-html p{font-size:12px}
@media(max-width:1024px){.fn-hero-title{font-size:58px!important;letter-spacing:-2px}.fn-section{padding:60px 30px!important}.fn-section>.kt-row-column-wrap{column-gap:32px}.fn-visual{padding:25px;min-height:360px}.fn-section-title{font-size:40px!important}}
@media(max-width:767px){.site-header-row-container-inner>.site-container{padding:0 22px}.site-branding .site-title{font-size:27px}.fn-section{padding:48px 22px!important}.fn-hero{padding-top:48px!important}.fn-hero-title{font-size:46px!important;letter-spacing:-1.8px}.fn-lead{font-size:17px!important}.fn-section-title{font-size:36px!important}.fn-section>.kt-row-column-wrap{row-gap:36px}.fn-visual{min-height:340px;padding:24px}.fn-visual-top{font-size:23px}.fn-kicker{padding:18px 22px;gap:9px 22px;font-size:12px;justify-content:flex-start}.fn-grid{gap:30px}.fn-card{margin-bottom:24px}.fn-contact-box{padding:24px}.fn-process>div{gap:15px}.fn-demo-notice{font-size:11px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{animation:none!important;transition:none!important}}

.fn-hero>.kt-row-column-wrap{align-items:center}.fn-grid .wp-block-kadence-column{border-top:2px solid var(--fn-ink);padding-top:24px}.fn-grid .fn-card-title{font-size:28px!important;line-height:1.25!important;letter-spacing:-.5px}.fn-grid p{color:var(--fn-muted);font-size:16px}#site-navigation a{font-size:14px;font-weight:600;color:var(--fn-ink)}
